const src = $input.first();
const form = src.json || {};
const binaries = src.binary || {};
const keys = Object.keys(binaries);

const pick = function (names) {
  for (const k of names) {
    const v = form[k];
    if (v !== undefined && v !== null && typeof v !== 'object' && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
const language = pick(['language', 'Sarunu valoda']) || 'automātiski';
const callDate = pick(['call_date', 'Zvanu datums (ja tukšs — šodiena)']).slice(0, 10);

const wavDurationSeconds = function (buf) {
  if (!buf || buf.length < 44) return null;
  if (buf.toString('ascii', 0, 4) !== 'RIFF' || buf.toString('ascii', 8, 12) !== 'WAVE') return null;
  let offset = 12;
  let byteRate = 0;
  while (offset + 8 <= buf.length) {
    const id = buf.toString('ascii', offset, offset + 4);
    const size = buf.readUInt32LE(offset + 4);
    if (id === 'fmt ') byteRate = buf.readUInt32LE(offset + 16);
    if (id === 'data') {
      const dataSize = Math.min(size, buf.length - offset - 8);
      return byteRate > 0 ? dataSize / byteRate : null;
    }
    offset += 8 + size + (size % 2);
  }
  return null;
};

const out = [];
for (const key of keys) {
  const file = binaries[key];
  const name = String(file.fileName || key);
  let seconds = null;
  if (name.toLowerCase().endsWith('.wav') || String(file.mimeType || '').indexOf('wav') !== -1) {
    try {
      const buf = await this.helpers.getBinaryDataBuffer(0, key);
      seconds = wavDurationSeconds(buf);
    } catch (e) {
      seconds = null;
    }
  }
  out.push({
    json: { file_name: name, language: language, call_date: callDate, audio_seconds: seconds },
    binary: { data: file },
    pairedItem: { item: 0 }
  });
}
return out;

