const out = $json.output || null;
const split = $('Split Files').item.json || {};
const tr = $('Transcribe Call').item.json || {};
const transcript = String(tr.text || '');
const criteriaText = String($('Review Criteria').item.json.criteria || '');

const errText = function (e) {
  if (!e) return '';
  if (typeof e === 'string') return e;
  return String(e.message || e.description || JSON.stringify(e));
};
const transcribeError = errText(tr.error);
const evaluateError = errText($json.error);
let errorMessage = '';
if (transcribeError) errorMessage = 'Atšifrēšanas kļūda: ' + transcribeError;
else if (!transcript.trim()) errorMessage = 'Atšifrējums ir tukšs';
else if (evaluateError) errorMessage = 'Novērtēšanas kļūda: ' + evaluateError;
else if (!out) errorMessage = 'AI neatgrieza novērtējumu';
const failed = errorMessage !== '';
const o = out || {};

const defined = criteriaText.split('\n').map(function (line) {
  const parts = line.split('|');
  return { id: (parts[0] || '').trim(), text: parts.slice(1).join('|').trim() };
}).filter(function (c) { return c.id && c.text; });

const answers = Array.isArray(o.criteria) ? o.criteria : [];
const findAnswer = function (id) {
  return answers.find(function (a) { return String(a.id || '').trim().toUpperCase() === id.toUpperCase(); });
};
const rows = defined.map(function (c) {
  const a = findAnswer(c.id);
  return { id: c.id, text: c.text, met: !failed && !!(a && a.met === true), evidence: a && a.evidence ? String(a.evidence) : 'Nav novērtēts' };
});
const total = rows.length;
const met = rows.filter(function (r) { return r.met; }).length;
const score = !failed && total > 0 ? Math.round((met / total) * 100) : 0;

const outcomeAllowed = ['piekrita', 'padomās', 'atteicās', 'nav skaidrs'];
const outcomeRaw = String(o.call_outcome || '').trim().toLowerCase();
const callOutcome = !failed && outcomeAllowed.indexOf(outcomeRaw) >= 0 ? outcomeRaw : 'nav skaidrs';

const clean = function (s) { const v = String(s || '').trim(); return v || 'Nav minēts'; };
const esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const br = function (s) { return esc(s).split('\n').join('<br>'); };
const listText = function (arr) {
  return Array.isArray(arr) && arr.length ? arr.map(function (s) { return '• ' + s; }).join('\n') : '—';
};

const riga = $now.setZone('Europe/Riga');
const callDate = String(split.call_date || '').slice(0, 10) || riga.toFormat('yyyy-LL-dd');
const language = String(split.language || '');
const fileName = String(split.file_name || '');
const employee = failed ? 'Nav zināms' : clean(o.employee_name);

const audioSeconds = Number(split.audio_seconds);
const wordCount = transcript.trim() ? transcript.trim().split(/\s+/).length : 0;
const durationEstimated = !(audioSeconds > 0);
const durationMin = durationEstimated ? Math.round((wordCount / 130) * 10) / 10 : Math.round((audioSeconds / 60) * 10) / 10;

const strengths = failed ? '—' : listText(o.strengths);
const missed = failed ? '—' : listText(o.missed);
const outcomeEvidence = failed ? '—' : clean(o.outcome_evidence);
const summary = failed ? errorMessage : String(o.summary || '');
const criteriaDetails = failed ? '—' : rows.map(function (r) { return (r.met ? '✔ ' : '✘ ') + r.id + ' ' + r.text + ' — ' + r.evidence; }).join('\n');
const info = function (v) { return failed ? '—' : clean(v); };

let reportHtml;
if (failed) {
  reportHtml = '<div style="border-top:1px solid #ddd;padding-top:8px;margin-top:16px">' +
    '<h3>' + esc(fileName) + ' — neizdevās apstrādāt</h3>' +
    '<p style="color:#b00020">' + esc(errorMessage) + '</p></div>';
} else {
  reportHtml = '<div style="border-top:1px solid #ddd;padding-top:8px;margin-top:16px">' +
    '<h3>' + esc(fileName) + ' — ' + score + '% (' + met + ' no ' + total + ')</h3>' +
    '<p><b>Darbinieks:</b> ' + esc(employee) + ' · <b>Ilgums:</b> ' + durationMin + ' min' + (durationEstimated ? ' (aptuveni)' : '') + ' · <b>Klienta lēmums:</b> ' + esc(callOutcome) + ' — ' + esc(outcomeEvidence) + '</p>' +
    '<p>' + br(summary) + '</p>' +
    '<p><b>Kritēriji</b><br>' + br(criteriaDetails) + '</p>' +
    '<p><b>Ko izdarīja labi</b><br>' + br(strengths) + '</p>' +
    '<p><b>Ko aizmirsa vai neizdarīja</b><br>' + br(missed) + '</p>' +
    '<p><b>Iegūtā informācija</b><br>' +
    'Kadastra nr.: ' + esc(info(o.cadastral_number)) + '<br>' +
    'Platība: ' + esc(info(o.property_area)) + '<br>' +
    'Ko pārdod: ' + esc(info(o.what_is_sold)) + '<br>' +
    'Cenas gaidas: ' + esc(info(o.price_expectation)) + '<br>' +
    'Nākamais solis: ' + esc(info(o.next_step)) + '</p></div>';
}

return {
  json: {
    call_date: callDate,
    uploaded_at: riga.toFormat('yyyy-LL-dd HH:mm'),
    employee: employee,
    file_name: fileName,
    language: language,
    status: failed ? 'kļūda' : 'ok',
    duration_min: durationMin,
    duration_estimated: durationEstimated,
    score_percent: score,
    criteria_met: met,
    criteria_total: total,
    call_outcome: callOutcome,
    outcome_evidence: outcomeEvidence,
    summary: summary,
    strengths: strengths,
    missed: missed,
    cadastral_number: info(o.cadastral_number),
    property_area: info(o.property_area),
    what_is_sold: info(o.what_is_sold),
    price_expectation: info(o.price_expectation),
    next_step: info(o.next_step),
    criteria_details: criteriaDetails,
    transcript: transcript,
    report_html: reportHtml
  }
};

const calls = $('Calculate Score').all().map(function (i) { return i.json; });
const ok = calls.filter(function (c) { return c.status === 'ok'; });
const failed = calls.filter(function (c) { return c.status !== 'ok'; });

const esc = function (s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); };
const sum = function (list, field) { return list.reduce(function (s, c) { return s + (Number(c[field]) || 0); }, 0); };

const totalMin = Math.round(sum(ok, 'duration_min') * 10) / 10;
const avgScore = ok.length ? Math.round(sum(ok, 'score_percent') / ok.length) : 0;
const anyEstimated = ok.some(function (c) { return c.duration_estimated; });
const outcomes = { 'piekrita': 0, 'padomās': 0, 'atteicās': 0, 'nav skaidrs': 0 };
ok.forEach(function (c) { outcomes[c.call_outcome] = (outcomes[c.call_outcome] || 0) + 1; });

const cell = 'padding:4px 8px;border-bottom:1px solid #eee;text-align:left';
const tableRows = calls.map(function (c) {
  const isOk = c.status === 'ok';
  return '<tr>' +
    '<td style="' + cell + '">' + esc(c.file_name) + '</td>' +
    '<td style="' + cell + '">' + esc(c.employee) + '</td>' +
    '<td style="' + cell + '">' + (isOk ? c.score_percent + '%' : 'kļūda') + '</td>' +
    '<td style="' + cell + '">' + (isOk ? esc(c.call_outcome) : '—') + '</td>' +
    '<td style="' + cell + '">' + (isOk ? c.duration_min + ' min' + (c.duration_estimated ? '*' : '') : '—') + '</td>' +
    '</tr>';
}).join('');

const html = '<div style="font-family:Arial,sans-serif;max-width:760px;margin:0 auto;text-align:left">' +
  '<h2>Apstrādāti zvani: ' + ok.length + ' no ' + calls.length + '</h2>' +
  '<p><b>Kopējais ilgums:</b> ' + totalMin + ' min · <b>Vidējais rezultāts:</b> ' + avgScore + '%</p>' +
  '<p><b>Klientu lēmumi:</b> piekrita ' + outcomes['piekrita'] + ' · padomās ' + outcomes['padomās'] + ' · atteicās ' + outcomes['atteicās'] + ' · nav skaidrs ' + outcomes['nav skaidrs'] + '</p>' +
  (failed.length ? '<p style="color:#b00020"><b>Neizdevās apstrādāt:</b> ' + failed.map(function (c) { return esc(c.file_name); }).join(', ') + '</p>' : '') +
  '<table style="border-collapse:collapse;width:100%;font-size:14px">' +
  '<tr><th style="' + cell + '">Fails</th><th style="' + cell + '">Darbinieks</th><th style="' + cell + '">Rezultāts</th><th style="' + cell + '">Klienta lēmums</th><th style="' + cell + '">Ilgums</th></tr>' +
  tableRows + '</table>' +
  (anyEstimated ? '<p style="color:#666;font-size:12px">* ilgums aprēķināts aptuveni pēc vārdu skaita</p>' : '') +
  calls.map(function (c) { return c.report_html; }).join('') +
  '<p style="color:#666;margin-top:16px">Rezultāti saglabāti tabulā call_reviews. AI vērtējums ir melnraksts — galīgo lēmumu pieņem vadītājs.</p>' +
  '</div>';

return [{ json: { summary_html: html, calls_total: calls.length, calls_ok: ok.length } }];

const NL = String.fromCharCode(10);
const items = $input.all();
const str = function (v) { return v === null || v === undefined ? '' : String(v); };

const parse = function (line) {
  const t = line.trim();
  const mark = t.charAt(0);
  if (mark !== '✔' && mark !== '✘') return null;
  const rest = t.slice(1).trim();
  const sp = rest.indexOf(' ');
  if (sp < 0) return null;
  const body = rest.slice(sp + 1);
  const dash = body.indexOf(' — ');
  return { id: rest.slice(0, sp), text: (dash >= 0 ? body.slice(0, dash) : body).trim() };
};

let latest = null;
items.forEach(function (i) {
  const r = i.json || {};
  if (r.status === 'kļūda' || !str(r.criteria_details).trim()) return;
  if (!latest || str(r.uploaded_at) >= str(latest.uploaded_at)) latest = r;
});
if (!latest) return items;

const current = {};
str(latest.criteria_details).split(NL).forEach(function (line) {
  const p = parse(line);
  if (p) current[p.id] = p.text;
});

return items.map(function (i) {
  const r = Object.assign({}, i.json);
  if (r.criteria_details) {
    r.criteria_details = str(r.criteria_details).split(NL).filter(function (line) {
      const p = parse(line);
      return p && current[p.id] === p.text;
    }).join(NL);
  }
  return { json: r };
});

const NL = String.fromCharCode(10);
const SQ = String.fromCharCode(39);
const DQ = String.fromCharCode(34);
const MAX_CELL = 32000;

const form = $('Report Request').first().json || {};
const str = function (v) { return v === null || v === undefined ? '' : String(v); };
const pick = function (keys) {
  for (const k of keys) {
    const v = form[k];
    if (v !== undefined && v !== null && typeof v !== 'object' && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};
const dateFrom = pick(['date_from']).slice(0, 10);
const dateTo = pick(['date_to']).slice(0, 10);
const empFilter = pick(['employee']);

const known = function (v) {
  const s = str(v).trim();
  return s !== '' && s !== '—' && s !== 'Nav minēts' && s !== 'Nav minēts sarunā';
};
const cut = function (v) {
  const s = str(v);
  return s.length > MAX_CELL ? s.slice(0, MAX_CELL) + ' …[saīsināts]' : s;
};

const parseCriteria = function (details) {
  const res = [];
  str(details).split(NL).forEach(function (raw) {
    const line = raw.trim();
    const mark = line.charAt(0);
    if (mark !== '✔' && mark !== '✘') return;
    const rest = line.slice(1).trim();
    const sp = rest.indexOf(' ');
    if (sp < 0) return;
    const body = rest.slice(sp + 1);
    const dash = body.indexOf(' — ');
    res.push({
      id: rest.slice(0, sp),
      met: mark === '✔',
      text: (dash >= 0 ? body.slice(0, dash) : body).trim(),
      quote: dash >= 0 ? body.slice(dash + 3).trim() : ''
    });
  });
  return res;
};

const rows = $input.all()
  .map(function (i) { return i.json; })
  .filter(function (r) { return r && r.call_date; })
  .filter(function (r) {
    const d = str(r.call_date).slice(0, 10);
    if (dateFrom && d < dateFrom) return false;
    if (dateTo && d > dateTo) return false;
    if (empFilter && str(r.employee).toLowerCase().indexOf(empFilter.toLowerCase()) === -1) return false;
    return true;
  });
rows.forEach(function (r) {
  r._ok = r.status !== 'kļūda';
  r._crit = parseCriteria(r.criteria_details);
  r._byId = {};
  r._crit.forEach(function (c) { r._byId[c.id] = c; });
});
const sortKey = function (r) { return str(r.call_date).slice(0, 10) + '|' + str(r.uploaded_at) + '|' + str(r.file_name); };
rows.sort(function (a, b) { const ka = sortKey(a); const kb = sortKey(b); return ka < kb ? -1 : ka > kb ? 1 : 0; });

const okRows = rows.filter(function (r) { return r._ok; });
const failedRows = rows.filter(function (r) { return !r._ok; });

let latest = null;
okRows.forEach(function (r) {
  if (r._crit.length && (!latest || str(r.uploaded_at) >= str(latest.uploaded_at))) latest = r;
});
const shortName = function (text) {
  const t = text.indexOf('Darbinieks ') === 0 ? text.slice(11) : text;
  return t.charAt(0).toUpperCase() + t.slice(1);
};
const criteria = latest ? latest._crit.map(function (c) { return { id: c.id, text: c.text, short: shortName(c.text) }; }) : [];

// ---------- XML and styles ----------
const xmlEsc = function (v) {
  const s = str(v);
  let clean = '';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code < 32 && code !== 9 && code !== 10 && code !== 13) continue;
