const fontList = [];
const fillList = [`<fill><patternFill patternType='none'/></fill>`, `<fill><patternFill patternType='gray125'/></fill>`];
const borderList = [`<border><left/><right/><top/><bottom/><diagonal/></border>`, `<border><left/><right/><top/><bottom style='thin'><color rgb='FFD9D9D9'/></bottom><diagonal/></border>`];
const xfList = [];
const styleCache = {};
const listIndex = function (list, xml) {
  let i = list.indexOf(xml);
  if (i < 0) { list.push(xml); i = list.length - 1; }
