};
const style = function (s) {
  const key = JSON.stringify(s);
  if (styleCache[key] !== undefined) return styleCache[key];
  const font = `<font>${s.bold ? '<b/>' : ''}${s.italic ? '<i/>' : ''}${s.underline ? '<u/>' : ''}<sz val='${s.size || 11}'/><color rgb='FF${s.color || '000000'}'/><name val='Calibri'/><family val='2'/></font>`;
  const fontId = listIndex(fontList, font);
  const fillId = s.fill ? listIndex(fillList, `<fill><patternFill patternType='solid'><fgColor rgb='FF${s.fill}'/><bgColor indexed='64'/></patternFill></fill>`) : 0;
  const borderId = s.border ? 1 : 0;
  const numFmtId = s.pct ? 9 : 0;
  const hasAlign = s.wrap || s.h || s.v;
  const align = hasAlign ? `<alignment${s.h ? ` horizontal='${s.h}'` : ''}${s.v ? ` vertical='${s.v}'` : ''}${s.wrap ? ` wrapText='1'` : ''}/>` : '';
  const attrs = `numFmtId='${numFmtId}' fontId='${fontId}' fillId='${fillId}' borderId='${borderId}' xfId='0' applyNumberFormat='1' applyFont='1' applyFill='1' applyBorder='1'${hasAlign ? ` applyAlignment='1'` : ''}`;
  const xf = hasAlign ? `<xf ${attrs}>${align}</xf>` : `<xf ${attrs}/>`;
  styleCache[key] = listIndex(xfList, xf);
  return styleCache[key];
};
style({});
