const mergeRange = function (r1, c1, r2, c2) { return colName(c1) + r1 + ':' + colName(c2) + r2; };
const makeSheet = function (name) {
  return { name: name, cells: {}, heights: {}, widths: [], merges: [], freeze: null, filter: null, links: [] };
