const scoreOf = function (r) { return (Number(r.score_percent) || 0) / 100; };
const avgScoreOf = function (list) { return list.length ? list.reduce(function (s, r) { return s + scoreOf(r); }, 0) / list.length : 0; };

const stats = criteria.map(function (c) {
  const judged = okRows.filter(function (r) { return r._byId[c.id]; });
  const missedRows = judged.filter(function (r) { return !r._byId[c.id].met; });
