// ---------- Build XLSX package ----------
const sheetXml = function (sh, selected) {
  let view = `<sheetView workbookViewId='0'${selected ? ` tabSelected='1'` : ''}`;
  if (sh.freeze) {
    const tl = colName(sh.freeze.col + 1) + (sh.freeze.row + 1);
    const pane = sh.freeze.col && sh.freeze.row ? 'bottomRight' : sh.freeze.row ? 'bottomLeft' : 'topRight';
    view += `><pane${sh.freeze.col ? ` xSplit='${sh.freeze.col}'` : ''}${sh.freeze.row ? ` ySplit='${sh.freeze.row}'` : ''} topLeftCell='${tl}' activePane='${pane}' state='frozen'/><selection pane='${pane}' activeCell='${tl}' sqref='${tl}'/></sheetView>`;
  } else {
    view += '/>';
  }
  const cols = sh.widths.length ? `<cols>${sh.widths.map(function (w, i) { return `<col min='${i + 1}' max='${i + 1}' width='${w}' customWidth='1'/>`; }).join('')}</cols>` : '';
  const parts = [];
  Object.keys(sh.cells).map(Number).sort(function (a, b) { return a - b; }).forEach(function (r) {
    const cells = sh.cells[r];
    const ht = sh.heights[r] ? ` ht='${sh.heights[r]}' customHeight='1'` : '';
    parts.push(`<row r='${r}'${ht}>`);
    Object.keys(cells).map(Number).sort(function (a, b) { return a - b; }).forEach(function (c) {
      const cell = cells[c];
      const ref = colName(c) + r;
      const s = cell.s ? ` s='${cell.s}'` : '';
      if (cell.v === null || cell.v === undefined || cell.v === '') parts.push(`<c r='${ref}'${s}/>`);
      else if (typeof cell.v === 'number' && isFinite(cell.v)) parts.push(`<c r='${ref}'${s}><v>${cell.v}</v></c>`);
      else parts.push(`<c r='${ref}'${s} t='inlineStr'><is><t xml:space='preserve'>${xmlEsc(cell.v)}</t></is></c>`);
    });
    parts.push('</row>');
